import React, { useState } from 'react';
import Sidebar from './Sidebar';
import TopBar from './TopBar';
import { useLayout } from '@/contexts/LayoutContext';
import { useTheme } from '@/contexts/ThemeContext';

const Layout = ({ children }) => {
  const [isMobileMenuOpen, setIsMobileMenuOpen] = useState(false);
  const { showSidebar, showTopBar } = useLayout();
  const { theme } = useTheme();

  return (
    <div className="flex h-screen overflow-hidden">
                <div className="fixed inset-0 z-0 pointer-events-none">
            <picture className="absolute inset-0 h-full w-full overflow-hidden"
           >
            {theme !== 'light' ? (
              <img
                src="data:image/jpeg;base64,"
                alt=""
                aria-hidden="true"
                className="absolute inset-0 h-full w-full scale-[1.02] object-cover opacity-50 blur-2xl"
              />) : (
                <img
                src="data:image/jpeg;base64,"
                alt=""
                aria-hidden="true"
                className="absolute inset-0 h-full w-full scale-[1.02] object-cover opacity-50 blur-2xl"
              />
              ) 
              }
            </picture>
            <div className={`absolute inset-0 h-full w-full bg-gradient-to-t from-transparent ${(theme === 'light') ? 'from-black to-black/40' : 'to-black/0'}`} />
          </div>
      {isMobileMenuOpen && (
        <div 
          className="fixed inset-0 bg-black/50 z-40 lg:hidden"
          onClick={() => setIsMobileMenuOpen(false)}
        />
      )}
      {showSidebar && (
        <div className={`
          fixed lg:relative inset-y-0 left-0 z-50 lg:z-auto
          transform ${isMobileMenuOpen ? 'translate-x-0' : '-translate-x-full lg:translate-x-0'}
          transition-transform duration-300 ease-in-out
        `}>
        <Sidebar />
      </div>
      )}
      <div className="flex-1 flex flex-col overflow-hidden">
        {showTopBar && (
          <TopBar 
            onMobileMenuToggle={() => setIsMobileMenuOpen(!isMobileMenuOpen)}
            isMobileMenuOpen={isMobileMenuOpen}
          />
        )}
        <main className={`flex-1 overflow-auto ${showTopBar ? "p-4 lg:p-6" : ""}`}>
          {children}
        </main>
      </div>
    </div>
  );
};

export default Layout;

